package accept

import (
	"fmt"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"strings"
)

// Directories whose content is regenerated by a run and never part of a tree.
var ignoredDirectories = map[string]bool{
	"__pycache__":   true,
	".pytest_cache": true,
	"test-results":  true,
}

const (
	treeDirectoryMode = 0o755
	treeFileMode      = 0o644
	oraclePrefix      = OracleSubdir + "/"
)

// Tree is a set of files by slash-separated path relative to the tree's root.
type Tree map[string][]byte

// ReadTree reads every file under dir.
func ReadTree(dir string) (Tree, error) {
	files := Tree{}
	err := filepath.WalkDir(dir, func(location string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if entry.IsDir() {
			if ignoredDirectories[entry.Name()] {
				return filepath.SkipDir
			}
			return nil
		}
		relative, err := filepath.Rel(dir, location)
		if err != nil {
			return err
		}
		content, err := os.ReadFile(location)
		if err != nil {
			return err
		}
		files[filepath.ToSlash(relative)] = content
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("read the files under %s: %w", dir, err)
	}
	return files, nil
}

// Clone copies the tree.
func (t Tree) Clone() Tree {
	copied := make(Tree, len(t))
	for name, content := range t {
		copied[name] = content
	}
	return copied
}

// Overlay returns the tree with each file of edits written at base/<its path>.
// It fails for an edit that would add a file the tree does not hold.
func (t Tree) Overlay(edits Tree, base string) (Tree, error) {
	merged := t.Clone()
	for _, name := range sortedKeys(edits) {
		target := path.Join(base, name)
		if _, exists := merged[target]; !exists {
			return nil, fmt.Errorf("%s edits %s, which the project does not hold", name, target)
		}
		merged[target] = edits[name]
	}
	return merged, nil
}

// Without returns the tree without the files under a directory prefix.
func (t Tree) Without(prefix string) Tree {
	kept := Tree{}
	for name, content := range t {
		if !strings.HasPrefix(name, prefix) {
			kept[name] = content
		}
	}
	return kept
}

// With returns the tree with the files of another added under a prefix.
func (t Tree) With(prefix string, added Tree) Tree {
	merged := t.Clone()
	for name, content := range added {
		merged[prefix+name] = content
	}
	return merged
}

// Write replaces dir with the tree.
func (t Tree) Write(dir string) error {
	if err := os.RemoveAll(dir); err != nil {
		return fmt.Errorf("clear %s: %w", dir, err)
	}
	if err := os.MkdirAll(dir, treeDirectoryMode); err != nil {
		return fmt.Errorf("create %s: %w", dir, err)
	}
	for _, name := range sortedKeys(t) {
		location := filepath.Join(dir, filepath.FromSlash(name))
		if err := os.MkdirAll(filepath.Dir(location), treeDirectoryMode); err != nil {
			return fmt.Errorf("create the directory of %s: %w", name, err)
		}
		if err := os.WriteFile(location, t[name], treeFileMode); err != nil {
			return fmt.Errorf("write %s: %w", name, err)
		}
	}
	return nil
}
